export async function authMiddleware(req: Request, next: NextFunction) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return next();
  try {
    const user = jwt.verify(token, process.env.JWT_SECRET!);
    req.user = user;
    next();
  } catch (e) {
    next();
  }
}
